using ShipmentTracker.Data;
using ShipmentTracker.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization();

builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<IdentityRedirectManager>();
builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();

builder.Services.AddAuthentication(options =>
    {
        options.DefaultScheme = IdentityConstants.ApplicationScheme;
        options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
    })
    .AddIdentityCookies();

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
builder.Services.AddDbContext<ApplicationDbContext>(options =>
    options.UseSqlite(connectionString));
builder.Services.AddDatabaseDeveloperPageExceptionFilter();

builder.Services.AddIdentityCore<ApplicationUser>(options =>
    {
        options.SignIn.RequireConfirmedAccount = true;
        options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
    })
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddSignInManager()
    .AddDefaultTokenProviders();

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddScoped<IShipmentService, ShipmentServerService>();

var app = builder.Build();

// Seed the database
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.EnsureCreated();
    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Data.Shipment { TrackingNumber = "TRK-001-ABC", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = (int)ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - Laptop" },
            new Data.Shipment { TrackingNumber = "TRK-002-DEF", Origin = "Chicago, IL", Destination = "Houston, TX", Status = (int)ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), ActualDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "bob@example.com", Description = "Books - Textbooks" },
            new Data.Shipment { TrackingNumber = "TRK-003-GHI", Origin = "Seattle, WA", Destination = "Miami, FL", Status = (int)ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "carol@example.com", Description = "Clothing - Winter Jacket" },
            new Data.Shipment { TrackingNumber = "TRK-004-JKL", Origin = "Boston, MA", Destination = "Denver, CO", Status = (int)ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "dave@example.com", Description = "Furniture - Office Chair" },
            new Data.Shipment { TrackingNumber = "TRK-005-MNO", Origin = "San Francisco, CA", Destination = "Atlanta, GA", Status = (int)ShipmentStatus.PickedUp, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "eve@example.com", Description = "Food - Gourmet Gift Basket" },
            new Data.Shipment { TrackingNumber = "TRK-006-PQR", Origin = "Dallas, TX", Destination = "Portland, OR", Status = (int)ShipmentStatus.Exception, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "frank@example.com", Description = "Fragile - Glass Vase" }
        );
        db.SaveChanges();
    }
}

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseWebAssemblyDebugging();
    app.UseMigrationsEndPoint();
}
else
{
    app.UseExceptionHandler("/Error", createScopeForErrors: true);
    // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
    app.UseHsts();
}
app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
app.UseHttpsRedirection();

app.UseAntiforgery();

app.MapStaticAssets();

// API Endpoints
app.MapGet("/api/shipments", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

app.MapGet("/api/shipments/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(id, newStatus);
    return Results.NoContent();
}).RequireAuthorization();

app.MapRazorComponents<App>()
    .AddInteractiveServerRenderMode()
    .AddInteractiveWebAssemblyRenderMode()
    .AddAdditionalAssemblies(typeof(ShipmentTracker.Client._Imports).Assembly);

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

