 @page "/track"
 @attribute [Authorize]
 @inject IShipmentService ShipmentService

 <PageTitle>Track Shipment</PageTitle>

 <h1>Track a Shipment</h1>

 <div class="mb-4">
     <div class="input-group" style="max-width: 500px;">
         <input type="text" class="form-control" placeholder="Enter tracking number" @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
         <button class="btn btn-primary" @onclick="Search">Track</button>
     </div>
 </div>

 @if (searched)
 {
     @if (shipment is not null)
     {
         <div class="card" style="max-width: 600px;">
             <div class="card-header">
                 <h5 class="mb-0">Shipment Details</h5>
             </div>
             <div class="card-body">
                 <dl class="row mb-0">
                     <dt class="col-sm-5">Tracking Number</dt>
                     <dd class="col-sm-7">@shipment.TrackingNumber</dd>

                     <dt class="col-sm-5">Origin</dt>
                     <dd class="col-sm-7">@shipment.Origin</dd>

                     <dt class="col-sm-5">Destination</dt>
                     <dd class="col-sm-7">@shipment.Destination</dd>

                     <dt class="col-sm-5">Status</dt>
                     <dd class="col-sm-7"><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>

                     <dt class="col-sm-5">Description</dt>
                     <dd class="col-sm-7">@shipment.Description</dd>

                     <dt class="col-sm-5">Shipped Date</dt>
                     <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                     <dt class="col-sm-5">Estimated Delivery</dt>
                     <dd class="col-sm-7">@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</dd>

                     <dt class="col-sm-5">Actual Delivery</dt>
                     <dd class="col-sm-7">@(shipment.ActualDelivery?.ToString("MMM dd, yyyy") ?? "Not yet delivered")</dd>
                 </dl>
             </div>
         </div>
     }
     else
     {
         <div class="alert alert-warning" style="max-width: 500px;">
             <strong>Not Found.</strong> No shipment found with tracking number "<strong>@searchedNumber</strong>". Please check the number and try again.
         </div>
     }
 }

 @code {
     private string trackingNumber = "";
     private string searchedNumber = "";
     private Shipment? shipment;
     private bool searched;

     private async Task Search()
     {
         if (string.IsNullOrWhiteSpace(trackingNumber)) return;
         searchedNumber = trackingNumber.Trim();
         shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
         searched = true;
     }

     private async Task HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             await Search();
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Exception => "bg-danger",
         _ => "bg-secondary"
     };
 }

